 79|/**
 80| * Detect the content type of a markdown block
 81| */
 82|export function detectContentType(text: string): ContentType {
 83|  // Check for monster (most specific - needs AC, HP, and abilities)
 84|  if (isMonster(text)) {
 85|    return ContentType.Monster;
 86|  }
 87|
 88|  // Check for spell (has casting time, range, components, duration)
 89|  if (isSpell(text)) {
 90|    return ContentType.Spell;
 91|  }
 92|
 93|  // Check for magic item
 94|  if (isItem(text)) {
 95|    return ContentType.Item;
 96|  }
 97|
 98|  // Check for chapter/episode headers
 99|  if (isChapter(text)) {
100|    return ContentType.Chapter;
101|  }
102|
103|  // Check for location descriptions
104|  if (isLocation(text)) {
105|    return ContentType.Location;
106|  }
107|
108|  // Check for NPC
109|  if (isNPC(text)) {
110|    return ContentType.NPC;
111|  }
112|
113|  // Check for DM notes
114|  if (isNote(text)) {
115|    return ContentType.Note;
116|  }
117|
118|  // Check for read-aloud text (blockquotes)
119|  if (isReadAloud(text)) {
120|    return ContentType.ReadAloud;
121|  }
122|
123|  // Check for tables
124|  if (isTable(text)) {
125|    return ContentType.Table;
126|  }
127|
128|  return ContentType.Unknown;
129|}
