131|/**
132| * Check if content is a monster stat block
133| */
134|function isMonster(text: string): boolean {
135|  const hasAC = patterns.monster.acPattern.test(text);
136|  const hasHP = patterns.monster.hpPattern.test(text);
137|  const hasAbilities =
138|    patterns.monster.abilityPattern.test(text) ||
139|    patterns.monster.abilityTablePattern.test(text);
140|
141|  // Must have at least AC and HP, preferably abilities too
142|  return hasAC && hasHP && hasAbilities;
143|}
144|
145|/**
146| * Check if content is a spell
147| */
148|function isSpell(text: string): boolean {
149|  // Must have at least 3 of the 4 spell components
150|  let matches = 0;
151|  if (patterns.spell.castingTimePattern.test(text)) matches++;
152|  if (patterns.spell.rangePattern.test(text)) matches++;
153|  if (patterns.spell.componentsPattern.test(text)) matches++;
154|  if (patterns.spell.durationPattern.test(text)) matches++;
155|
156|  // Or has a spell level line
157|  const hasLevel =
158|    patterns.spell.levelPattern.test(text) ||
159|    patterns.spell.cantripPattern.test(text);
