 13|
 14|/**
 15| * Parse markdown string into content blocks
 16| */
 17|export function parseMarkdown(content: string): ContentBlock[] {
 18|  // Extract frontmatter if present
 19|  const { content: markdownContent, data: frontmatter } = matter(content);
 20|
 21|  // Split by major headers (# and ##)
 22|  const blocks = splitByHeaders(markdownContent);
 23|
 24|  // Detect type for each block
 25|  return blocks.map((block, index) => {
 26|    const type = detectContentType(block.content);
 27|    return {
 28|      type,
 29|      rawContent: block.content,
 30|      header: block.header,
 31|      metadata: index === 0 ? frontmatter : undefined,
 32|      lineNumber: block.lineNumber,
 33|    };
 34|  });
 35|}
 36|
 37|interface RawBlock {
 38|  header?: string;
 39|  content: string;
 40|  lineNumber: number;
 41|}
 42|
 43|/**
 44| * Split markdown by headers, keeping content with its header
 45| */
 46|function splitByHeaders(markdown: string): RawBlock[] {
 47|  const lines = markdown.split('\n');
 48|  const blocks: RawBlock[] = [];
 49|  let currentBlock: RawBlock | null = null;
 50|  let lineNumber = 1;
 51|
 52|  for (const line of lines) {
 53|    // Check for major headers (# or ##)
 54|    const headerMatch = line.match(/^(#{1,2})\s+(.+)$/);
 55|
 56|    if (headerMatch) {
 57|      // Save previous block if exists
 58|      if (currentBlock && currentBlock.content.trim()) {
 59|        blocks.push(currentBlock);
 60|      }
 61|
 62|      // Start new block
 63|      currentBlock = {
 64|        header: headerMatch[2],
 65|        content: line + '\n',
 66|        lineNumber,
 67|      };
 68|    } else {
 69|      // Add to current block or start new one
 70|      if (!currentBlock) {
 71|        currentBlock = {
 72|          content: line + '\n',
 73|          lineNumber,
 74|        };
 75|      } else {
 76|        currentBlock.content += line + '\n';
 77|      }
 78|    }
 79|
 80|    lineNumber++;
 81|  }
 82|
 83|  // Don't forget the last block
 84|  if (currentBlock && currentBlock.content.trim()) {
 85|    blocks.push(currentBlock);
 86|  }
 87|
 88|  // Post-process: merge small blocks that belong together
 89|  return mergeRelatedBlocks(blocks);
 90|}
 91|
 92|/**
 93| * Merge blocks that should stay together
 94| * (e.g., monster stat blocks spread across multiple sections)
 95| */
 96|function mergeRelatedBlocks(blocks: RawBlock[]): RawBlock[] {
 97|  const merged: RawBlock[] = [];
 98|
 99|  for (let i = 0; i < blocks.length; i++) {
100|    const block = blocks[i];
101|    const prevBlock = merged[merged.length - 1];

98|
 99|  for (let i = 0; i < blocks.length; i++) {
100|    const block = blocks[i];
101|    const prevBlock = merged[merged.length - 1];
102|
103|    // Check if this block is a continuation of a monster stat block
104|    if (prevBlock && shouldMergeWithPrevious(prevBlock, block)) {
105|      prevBlock.content += '\n' + block.content;
106|    } else {
107|      merged.push({ ...block });
108|    }
109|  }
110|
111|  return merged;
112|}
113|
114|/**
115| * Determine if a block should be merged with the previous one
116| */
117|function shouldMergeWithPrevious(prev: RawBlock, current: RawBlock): boolean {
118|  // If previous is a monster and current has "Actions" header, merge
119|  const prevType = detectContentType(prev.content);
120|  if (prevType === ContentType.Monster) {
121|    if (current.header?.toLowerCase().includes('action')) {
122|      return true;
123|    }
124|    if (current.header?.toLowerCase().includes('reaction')) {
125|      return true;
126|    }
127|    if (current.header?.toLowerCase().includes('legendary')) {
128|      return true;
129|    }
130|  }
131|
132|  return false;
133|}
