135|/**
136| * Extract blockquotes from content
137| */
138|export function extractBlockquotes(content: string): string[] {
139|  const lines = content.split('\n');
140|  const blockquotes: string[] = [];
141|  let currentQuote: string[] = [];
142|
143|  for (const line of lines) {
144|    if (line.startsWith('>')) {
145|      // Remove the > prefix and add to current quote
146|      currentQuote.push(line.replace(/^>\s?/, ''));
147|    } else if (currentQuote.length > 0) {
148|      // End of blockquote
149|      blockquotes.push(currentQuote.join('\n'));
150|      currentQuote = [];
151|    }
152|  }
153|
154|  // Don't forget the last quote
155|  if (currentQuote.length > 0) {
156|    blockquotes.push(currentQuote.join('\n'));
157|  }
158|
159|  return blockquotes;
160|}
