122|/**
123| * Add drop caps to chapter starts
124| */
125|export function insertDropCaps(content: string): string {
126|  const lines = content.split('\n');
127|  const result: string[] = [];
128|  let blockDepth = 0;
129|  let justSawChapter = false;
130|  let afterPageBreak = false;
131|
132|  for (let i = 0; i < lines.length; i++) {
133|    const line = lines[i];
134|
135|    // Track block depth properly
136|    const opens = (line.match(/\{\{/g) || []).length;
137|    const closes = (line.match(/\}\}/g) || []).length;
138|    blockDepth += opens - closes;
139|
140|    // Track page breaks
141|    if (line.includes('\\page')) {
142|      afterPageBreak = true;
143|      result.push(line);
144|      continue;
145|    }
146|
147|    // Check for chapter headers (only after page break or at top level)
148|    if ((afterPageBreak || i < 20) && blockDepth === 0 && line.match(/^##?\s+[A-Z]/)) {
149|      justSawChapter = true;
150|      afterPageBreak = false;
151|      result.push(line);
152|      continue;
153|    }
154|
155|    // Add drop cap to first paragraph after chapter
156|    // Must be: outside blocks, regular text starting with letter, not special syntax
157|    if (justSawChapter && blockDepth === 0 && line.trim()) {
158|      const trimmed = line.trim();
159|      // Skip if starts with special characters or is just braces
160|      if (trimmed.match(/^[A-Z]/) &&
161|          !trimmed.startsWith('#') &&
162|          !trimmed.startsWith('*') &&
163|          !trimmed.startsWith('>') &&
164|          !trimmed.startsWith('|') &&
165|          !trimmed.startsWith('{') &&
166|          !trimmed.startsWith('}') &&
167|          !trimmed.startsWith('!')

168|          !trimmed.startsWith('[') &&
169|          !line.startsWith('{{dropcap')) {
170|        const firstLetter = trimmed[0];
171|        const rest = trimmed.substring(1);
172|        result.push(`{{dropcap ${firstLetter}}}${rest}`);
173|        justSawChapter = false;
174|        continue;
175|      }
176|    }
177|
178|    // Reset chapter flag on any non-empty non-header content
179|    if (line.trim() && !line.startsWith('#') && blockDepth === 0) {
180|      justSawChapter = false;
181|    }
182|
183|    result.push(line);
184|  }
185|
186|  return result.join('\n');
187|}
