192|export function addPageNumbers(content: string): string {
193|  // Check if already has page numbers
194|  if (content.includes('{{pageNumber')) {
195|    return content;
196|  }
197|
198|  const pages = content.split('\\page');
199|  const result: string[] = [];
200|
