211|    const pageNum = `\n\n{{pageNumber,auto}}\n{{footnote PART ${getRomanNumeral(Math.ceil(i / 5))}}}`;
212|    page = page + pageNum;
213|    result.push(page);
214|  }
215|
216|  return result.join('\\page');
