243|/**
244| * Convert to Roman numeral
245| */
246|function getRomanNumeral(num: number): string {
247|  const numerals: Array<[number, string]> = [
248|    [10, 'X'],
249|    [9, 'IX'],
250|    [5, 'V'],
251|    [4, 'IV'],
252|    [1, 'I'],
253|  ];
254|
255|  let result = '';
256|  let remaining = num;
257|
258|  for (const [value, symbol] of numerals) {
259|    while (remaining >= value) {
260|      result += symbol;
261|      remaining -= value;
262|    }
263|  }
264|
265|  return result;
266|}
