318|/**
319| * Clean up redundant structural elements
320| */
321|export function cleanupStructure(content: string): string {
322|  let result = content;
323|
324|  // Remove duplicate page breaks
325|  result = result.replace(/\\page\s*\\page/g, '\\page');
326|
