 9|export function extractChapter(content: string): { title: string; body: string } {
10|  const lines = content.split('\n');
11|  let title = '';
12|  let bodyLines: string[] = [];
13|  let foundHeader = false;
14|
15|  for (const line of lines) {
16|    // Check for episode/chapter header
17|    const episodeMatch = line.match(/^#\s*(Episode\s+\d+\s*[:.-]?\s*(.*))/i);
18|    const chapterMatch = line.match(/^#\s*(Chapter\s+\d+\s*[:.-]?\s*(.*))/i);
19|    const partMatch = line.match(/^#\s*(Part\s+\d+\s*[:.-]?\s*(.*))/i);
20|
21|    if ((episodeMatch || chapterMatch || partMatch) && !foundHeader) {
22|      const match = episodeMatch || chapterMatch || partMatch;
23|      title = match![1].trim();
24|      foundHeader = true;
25|      continue;
26|    }
27|
28|    // Add to body after header found
29|    if (foundHeader) {
30|      bodyLines.push(line);
31|    }
32|  }
33|
34|  return {
35|    title: title || 'Untitled Chapter',
36|    body: bodyLines.join('\n').trim(),
37|  };
