193|/**
194| * Parse part number from string (handles "1", "I", "One", etc.)

195| */
196|function parsePartNumber(str: string): number {
197|  // Try numeric
198|  const num = parseInt(str, 10);
199|  if (!isNaN(num)) return num;
200|
201|  // Try roman numerals
202|  const romanMap: Record<string, number> = {
203|    'I': 1, 'II': 2, 'III': 3, 'IV': 4, 'V': 5,
204|    'VI': 6, 'VII': 7, 'VIII': 8, 'IX': 9, 'X': 10,
205|  };
206|  if (romanMap[str.toUpperCase()]) {
207|    return romanMap[str.toUpperCase()];
208|  }
209|
210|  // Try words
211|  const wordMap: Record<string, number> = {
212|    'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
213|    'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
214|  };
215|  if (wordMap[str.toLowerCase()]) {
216|    return wordMap[str.toLowerCase()];
217|  }
218|
219|  return 1;
220|}
