286|    const text = match.replace(/\n?>/g, '').trim();
287|    return `\n{{descriptive\n${text}\n}}`;
288|  });
289|
290|  // Clean up extra blank lines
291|  result = result.replace(/\n{4,}/g, '\n\n\n');
292|
293|  // Ensure all monster blocks are closed
294|  const monsterOpens = (result.match(/\{\{monster,frame/g) || []).length;
295|  if (monsterOpens > 0) {
296|    result = result.replace(
297|      /(\{\{monster,frame[\s\S]*?

