  3|/**
  4| * Parse magic item from content
  5| */
  6|export function parseItem(content: string): ItemData {
  7|  const item: ItemData = {
  8|    name: 'Unknown Item',
  9|    description: '',
 10|  };
 11|
 12|  // Extract name from header
 13|  const headerMatch = content.match(/^#{1,4}\s*(?:(?:Magic\s+)?Item:\s*)?(.+)$/im);
 14|  if (headerMatch) {
 15|    item.name = headerMatch[1].trim();
 16|  }
 17|
 18|  // Extract rarity
 19|  const rarityMatch = content.match(/\b(common|uncommon|rare|very rare|legendary|artifact)\b/i);
 20|  if (rarityMatch) {
 21|    item.rarity = rarityMatch[1].toLowerCase();
 22|  }
 23|
 24|  // Extract type - expanded list
 25|  const typePatterns = [
 26|    'weapon',
 27|    'armor',
 28|    'wondrous item',
 29|    'ring',
 30|    'rod',
 31|    'staff',
 32|    'wand',
 33|    'potion',
 34|    'scroll',
 35|    'amulet',
 36|    'cloak',
 37|    'boots',
 38|    'gloves',
 39|    'helm',
 40|    'shield',
 41|    'belt',
 42|    'bracers',
 43|    'circlet',
 44|    'mask',
 45|    'tome',
 46|    'grimoire',
 47|    'codex',
 48|    'orb',
 49|  ];
 50|
 51|  for (const pattern of typePatterns) {
 52|    const regex = new RegExp(`\\b${pattern}\\b`, 'i');
 53|    if (regex.test(content)) {
 54|      item.type = pattern;
 55|      break;
 56|    }
 57|  }
 58|
 59|  // Check for attunement and parse specific requirements
 60|  const attunementMatch = content.match(/requires attunement(?: by (?:a |an )?([^)]+))?/i);
 61|  if (attunementMatch) {
 62|    item.attunement = true;
 63|    if (attunementMatch[1]) {
 64|      item.attunementBy = attunementMatch[1].trim();
 65|    }
 66|  } else {
 67|    item.attunement = false;
 68|  }
 69|
 70|  // Extract description (everything after type/rarity line)
 71|  const lines = content.split('\n');
 72|  let inDescription = false;
 73|  const descLines: string[] = [];
 74|
 75|  for (const line of lines) {
 76|    // Skip header
 77|    if (line.match(/^#{1,4}/)) continue;
 78|
 79|    // Skip type/rarity line (usually italic)
 80|    if (line.match(/^\*[^*]+\*$/) && !inDescription) {
 81|      inDescription = true;
 82|      continue;
 83|    }
 84|
 85|    if (inDescription || !line.match(/\b(common|uncommon|rare|weapon|armor|requires attunement)/i)) {
 86|      if (line.trim()) {
 87|        descLines.push(line);
 88|        inDescription = true;
 89|      }
 90|    }
 91|  }
 92|
 93|  item.description = descLines.join('\n').trim();
 94|
 95|  return item;
 96|}
