50|export function transformLocation(content: string): string {
51|  const { name, description } = extractLocation(content);
52|
53|  const lines: string[] = [];
54|
55|  // Use wide block for location header
56|  lines.push('{{wide');
57|  lines.push(`## ${name}`);
58|
59|  // First paragraph as italic description
60|  const paragraphs = description.split('\n\n');
61|  if (paragraphs.length > 0 && paragraphs[0].trim()) {
62|    lines.push(`*${paragraphs[0].trim()}*`);
63|  }
64|
65|  lines.push('}}');
66|
67|  // Add remaining paragraphs outside the wide block
68|  if (paragraphs.length > 1) {
69|    lines.push('');
70|    lines.push(paragraphs.slice(1).join('\n\n'));
71|  }
72|
73|  return lines.join('\n');
