657|    }
658|  }
659|
660|  // Slot-based spells
661|  if (data.spells.slots) {
662|    const sortedLevels = Object.keys(data.spells.slots).sort((a, b) => parseInt(a) - parseInt(b));
663|    for (const level of sortedLevels) {
