16|export function extractNoteContent(content: string): { title: string; body: string } {
17|  // Match note header
18|  const headerMatch = content.match(/\*?\*?(DM Note|Note|Secret|Hidden|Tip|Warning|Important)\*?\*?\s*[:=]\s*(.*)/i);
19|
20|  if (!headerMatch) {
