  7|  const lines = content.split('\n').filter((line) => line.trim());
  8|
  9|  const table: TableData = {
 10|    headers: [],
 11|    rows: [],
 12|    style: 'default',
 13|  };
 14|
 15|  // Extract title if present (header before table)
 16|  const titleMatch = content.match(/^#{1,4}\s+(.+)$/m);
 17|  if (titleMatch) {
 18|    table.title = titleMatch[1].trim();
 19|  }
 20|
 21|  // Find table rows
 22|  const tableLines = lines.filter((line) => line.trim().startsWith('|'));
 23|  if (tableLines.length < 2) return table;
 24|
 25|  // First line is headers
 26|  const headerLine = tableLines[0];
 27|  table.headers = parseTableRow(headerLine);
 28|
 29|  // Second line is alignment (|---|---|)
 30|  const alignLine = tableLines[1];
 31|  table.alignment = parseAlignment(alignLine);
 32|
 33|  // Rest are data rows
 34|  for (let i = 2; i < tableLines.length; i++) {
 35|    const row = parseTableRow(tableLines[i]);
 36|    if (row.length > 0) {
 37|      table.rows.push(row);
 38|    }
 39|  }
 40|
 41|  // Detect table style
 42|  table.style = detectTableStyle(table.headers, table.rows);
 43|
 44|  // Detect dice column for roll tables
 45|  if (table.style === 'roll') {
 46|    table.diceColumn = findDiceColumn(table.headers);
 47|  }
