 52|/**
 53| * Parse a single table row into cells
 54| */
 55|function parseTableRow(line: string): string[] {
 56|  // Remove leading and trailing pipes, then split
 57|  const trimmed = line.replace(/^\||\|$/g, '');
 58|  return trimmed.split('|').map((cell) => cell.trim());
 59|}
 60|
 61|/**
 62| * Parse alignment from separator row
 63| */
 64|function parseAlignment(line: string): ('left' | 'center' | 'right')[] {
 65|  const cells = parseTableRow(line);
 66|  return cells.map((cell) => {
 67|    const trimmed = cell.replace(/\s/g, '');
 68|    if (trimmed.startsWith(':') && trimmed.endsWith(':')) {
 69|      return 'center';
 70|    } else if (trimmed.endsWith(':')) {
 71|      return 'right';
 72|    }
 73|    return 'left';
 74|  });
 75|}
