 77|/**
 78| * Detect appropriate table style based on content
 79| */
 80|export function detectTableStyle(headers: string[], rows: string[][]): 'default' | 'class' | 'roll' {
 81|  const headerLower = headers.map((h) => h.toLowerCase());
 82|
 83|  // Roll tables have dice notation in headers or first column
 84|  if (headerLower.some((h) => /^d\d+$/.test(h)) ||
 85|      headerLower.includes('roll') ||
 86|      headerLower.includes('dice')) {
 87|    return 'roll';
 88|  }
 89|
 90|  // Check if first column contains dice notation (d20, d6, etc.)

91|  if (rows.length > 0) {
 92|    const firstCol = rows.map((row) => row[0] || '');
 93|    if (firstCol.some((cell) => /^\d+(-\d+)?$/.test(cell) || /^d\d+/.test(cell))) {
 94|      return 'roll';
 95|    }
 96|  }
 97|
 98|  // Class tables have level, proficiency, or feature columns
 99|  if (headerLower.includes('level') ||
100|      headerLower.includes('proficiency bonus') ||
101|      headerLower.includes('features') ||
102|      headerLower.includes('slots')) {
103|    return 'class';
104|  }
105|
106|  return 'default';
107|}
108|
109|/**
110| * Find the column index containing dice rolls
111| */
112|function findDiceColumn(headers: string[]): number {
113|  const headerLower = headers.map((h) => h.toLowerCase());
114|
115|  // Look for explicit dice header
116|  const diceIndex = headerLower.findIndex((h) => /^d\d+$/.test(h) || h === 'roll' || h === 'dice');
117|  if (diceIndex >= 0) return diceIndex;
118|
119|  // Default to first column for roll tables
120|  return 0;
121|}
