123|/**
124| * Transform table data to Homebrewery format
125| */
126|export function transformTable(data: TableData): string {
127|  const lines: string[] = [];
128|
129|  // Open table block based on style
130|  if (data.style === 'class') {
131|    lines.push('{{classTable,frame');
132|  } else if (data.style === 'roll') {
133|    lines.push('{{classTable,frame,wide');
134|  }
135|
136|  // Add title if present
137|  if (data.title) {
138|    lines.push(`##### ${data.title}`);
139|  }
140|
141|  // Build header row
142|  lines.push(`| ${data.headers.join(' | ')} |`);
143|
144|  // Build alignment row
145|  const alignRow = (data.alignment || data.headers.map(() => 'left' as const)).map((align) => {
146|    switch (align) {
147|      case 'center':
148|        return ':---:';
149|      case 'right':
150|        return '---:';
151|      default:
152|        return ':---';
153|    }
154|  });
155|  lines.push(`|${alignRow.join('|')}|`);
156|
157|  // Build data rows
158|  for (const row of data.rows) {
159|    // Pad row to match header length
160|    const paddedRow = [...row];
161|    while (paddedRow.length < data.headers.length) {
162|      paddedRow.push('');
163|    }
164|    lines.push(`| ${paddedRow.join(' | ')} |`);
165|  }
166|
167|  // Close table block if styled
168|  if (data.style === 'class' || data.style === 'roll') {
169|    lines.push('}}');
170|  }
171|
172|  return lines.join('\n');
173|}
