188|  const tableLines = content.split('\n').filter((line) => line.trim().startsWith('|'));
189|  if (tableLines.length < 2) return false;
190|
191|  // Check for separator row (|---|---|)
192|  const hasSeparator = tableLines.some((line) => /^\|[-:\s|]+\|$/.test(line));
193|  return hasSeparator;
