 19|
 20|      // Add chapters within this part
 21|      const partChapters = structure.chapters.filter((c) => c.partNumber === part.number);
 22|      for (const chapter of partChapters) {
 23|        lines.push(`  - #### ${chapter.title}`);
 24|
 25|        // Add sections if depth allows
 26|        if (depth >= 3 && chapter.sections.length > 0) {
 27|          for (const section of chapter.sections) {
 28|            lines.push(`    - ${section}`);
 29|          }
 30|        }
 31|      }
 32|    }
 33|  } else {
 34|    // No parts, just chapters
 35|    for (const chapter of structure.chapters) {
 36|      lines.push(`- ### ${chapter.title}`);
 37|
 38|      if (depth >= 2 && chapter.sections.length > 0) {
 39|        for (const section of chapter.sections) {
