 67|export function generateTOCFromEntries(entries: TOCEntry[]): string {
 68|  const lines: string[] = [];
 69|
 70|  lines.push('# Table of Contents');
 71|  lines.push('');
 72|  lines.push('{{toc,wide}}');
 73|  lines.push('');
 74|
 75|  for (const entry of entries) {
 76|    const indent = '  '.repeat(entry.level - 1);
 77|    const header = getHeaderForLevel(entry.level);
 78|    lines.push(`${indent}- ${header}${entry.title}`);
 79|
 80|    if (entry.children) {
 81|      for (const child of entry.children) {
 82|        const childLines = renderTOCEntry(child, entry.level + 1);
 83|        lines.push(...childLines);
 84|      }
 85|    }
 86|  }
 87|
 88|  lines.push('');
 89|  lines.push('}}');
 90|  lines.push('');
 91|  lines.push('\\page');

 84|      }
 85|    }
 86|  }
 87|
 88|  lines.push('');
 89|  lines.push('}}');
 90|  lines.push('');
 91|  lines.push('\\page');
 92|
 93|  return lines.join('\n');
