 96|/**
 97| * Render a single TOC entry with its children
 98| */
 99|function renderTOCEntry(entry: TOCEntry, level: number): string[] {
100|  const lines: string[] = [];
101|  const indent = '  '.repeat(level - 1);
102|  const header = getHeaderForLevel(level);
103|
104|  lines.push(`${indent}- ${header}${entry.title}`);
105|
106|  if (entry.children) {
107|    for (const child of entry.children) {
108|      lines.push(...renderTOCEntry(child, level + 1));
109|    }
110|  }
111|
112|  return lines;
