115|/**
116| * Get markdown header prefix for TOC level
117| */
118|function getHeaderForLevel(level: number): string {
119|  switch (level) {
120|    case 1:
121|      return '### ';
122|    case 2:
123|      return '#### ';
124|    case 3:
125|      return '##### ';
126|    default:
127|      return '';
128|  }
