131|/**
132| * Convert number to roman numeral
133| */
134|function romanNumeral(num: number): string {
135|  const numerals: Array<[number, string]> = [
136|    [10, 'X'],
137|    [9, 'IX'],
138|    [5, 'V'],
139|    [4, 'IV'],
140|    [1, 'I'],
141|  ];
142|
143|  let result = '';
144|  let remaining = num;
145|
146|  for (const [value, symbol] of numerals) {
147|    while (remaining >= value) {
148|      result += symbol;
149|      remaining -= value;
150|    }
151|  }
152|
153|  return result;
154|}
