163|  // Stack to track parent entries for nesting
164|  const stack: Array<{ entry: TOCEntry; level: number }> = [];
165|
166|  for (const line of lines) {
167|    // Match headers (# to ####)
168|    const headerMatch = line.match(/^(#{1,4})\s+(.+)$/);
169|    if (!headerMatch) continue;
