180|      continue;
181|    }
182|
183|    const entry: TOCEntry = {
184|      level,
185|      title,
186|      children: [],
187|    };
188|
189|    // Find parent
190|    while (stack.length > 0 && stack[stack.length - 1].level >= level) {
191|      stack.pop();
