193|
194|    if (stack.length === 0) {
195|      entries.push(entry);
196|    } else {
197|      const parent = stack[stack.length - 1].entry;
198|      if (!parent.children) parent.children = [];
199|      parent.children.push(entry);
200|    }
201|
202|    stack.push({ entry, level });

198|      if (!parent.children) parent.children = [];
199|      parent.children.push(entry);
200|    }
201|
202|    stack.push({ entry, level });
