208|/**
209| * Build document structure from content
210| */
211|export function buildDocumentStructure(content: string): DocumentStructure {
212|  const structure: DocumentStructure = {
213|    hasCover: false,
214|    hasInsideCover: false,
215|    hasToc: false,
216|    parts: [],
217|    chapters: [],
218|    appendices: [],
219|  };
220|
221|  const lines = content.split('\n');
222|
223|  // Extract title from first major header
224|  const titleMatch = content.match(/^#\s+(.+)$/m);
225|  if (titleMatch) {
226|    structure.title = titleMatch[1].trim();
227|  }
228|
229|  // Check for existing Homebrewery structures
230|  structure.hasCover = /\{\{cover\}\}/i.test(content);
231|  structure.hasInsideCover = /\{\{insideCover\}\}/i.test(content);
232|  structure.hasToc = /\{\{toc/i.test(content);
233|
234|  let currentPart = 0;
235|  let chapterNumber = 0;
236|  let currentChapter: ChapterInfo | null = null;
237|
238|  for (let i = 0; i < lines.length; i++) {
239|    const line = lines[i];
240|
241|    // Detect part headers
242|    const partMatch = line.match(/^#\s+(?:Part|Act)\s+(\d+|[IVX]+)(?::\s*|\s+)(.+)$/i);
243|    if (partMatch) {
244|      currentPart++;
245|      structure.parts.push({
246|        number: currentPart,
247|        title: partMatch[2].trim(),
248|        startLine: i,
249|        chapters: [],
250|      });
251|      continue;
252|    }
253|
254|    // Detect chapter headers
255|    const chapterMatch = line.match(/^##\s+(?:Chapter\s+)?(\d+)?(?::\s*|\s+)?(.+)$/i);
256|    if (chapterMatch && !line.toLowerCase().includes('appendix')) {
257|      chapterNumber++;
258|      currentChapter = {
259|        number: chapterNumber,
260|        title: chapterMatch[2]?.trim() || chapterMatch[1]?.trim() || 'Untitled',
261|        startLine: i,
262|        sections: [],
263|        partNumber: currentPart > 0 ? currentPart : undefined,
264|      };
265|      structure.chapters.push(currentChapter);
266|
267|      // Add to current part's chapter list
268|      if (currentPart > 0 && structure.parts.length > 0) {
269|        structure.parts[structure.parts.length - 1].chapters.push(chapterNumber);
270|      }
271|      continue;
272|    }
273|
274|    // Detect appendix headers
275|    const appendixMatch = line.match(/^##\s+Appendix\s+([A-Z])(?

276|    if (appendixMatch) {
277|      structure.appendices.push({
278|        letter: appendixMatch[1].toUpperCase(),
279|        title: appendixMatch[2].trim(),
280|        startLine: i,
281|      });
282|      currentChapter = null;
283|      continue;
284|    }
285|
286|    // Detect section headers within chapters
287|    const sectionMatch = line.match(/^###\s+(.+)$/);
288|    if (sectionMatch && currentChapter) {
289|      currentChapter.sections.push(sectionMatch[1].trim());
290|    }
291|  }
292|
293|  return structure;
