296|/**
297| * Check if content needs a TOC
298| */
299|export function needsTOC(content: string): boolean {
300|  // Already has TOC
301|  if (/\{\{toc/i.test(content)) {
302|    return false;
303|  }
304|
305|  // Count major headers
306|  const headers = content.match(/^##?\s+.+$/gm) || [];
307|  return headers.length >= 5;
