172| */
173|export function checkBlockNesting(content: string): ValidationWarning[] {
174|  const warnings: ValidationWarning[] = [];
175|  const pairs = findBlockPairs(content);
176|
177|  // Check for suspicious patterns
178|  for (const pair of pairs) {
179|    // Monster blocks should not be nested inside note blocks
180|    if (pair.type === 'monster') {
181|      const innerContent = pair.content;
182|      if (/\{\{note/.test(innerContent) && !/\}\}[\s\S]*\{\{note/.test(innerContent)) {
183|        warnings.push({
184|          type: 'unclosed_block',
185|          message: `Monster block at line ${pair.openLine} may have nested note block - verify structure`,
186|          line: pair.openLine,
187|          suggestion: 'Ensure monster and note blocks do not overlap',
188|        });
189|      }
190|    }
191|
192|    // Wide blocks should typically span full pages
193|    if (pair.type === 'wide' && pair.closeLine) {
194|      const lineSpan = pair.closeLine - pair.openLine;
195|      if (lineSpan < 3) {
196|        warnings.push({
197|          type: 'sparse_content',
198|          message: `Wide block at line ${pair.openLine} spans only ${lineSpan} lines`,
199|          line: pair.openLine,
200|          suggestion: 'Wide blocks are typically used for larger content sections',
201|        });
202|      }
203|    }
204|  }
205|
206|  return warnings;
