 28|export function estimatePages(content: string): PageEstimate[] {
 29|  const pages: PageEstimate[] = [];
 30|  const pageContents = content.split(/\\page/);
 31|
 32|  let currentLine = 1;
 33|
 34|  for (let i = 0; i < pageContents.length; i++) {
 35|    const pageContent = pageContents[i];
 36|    const lines = pageContent.split('\n');
 37|    const startLine = currentLine;
 38|
 39|    // Calculate effective line count
 40|    let effectiveLines = 0;
 41|
 42|    for (const line of lines) {
 43|      // Skip empty lines in calculation
 44|      if (!line.trim()) {
 45|        effectiveLines += 0.2; // Empty lines still take some space
 46|        continue;
 47|      }
 48|
 49|      // Headers take more space
 50|      if (line.match(/^#{1,6}/)) {
 51|        effectiveLines += 2;
 52|        continue;
 53|      }
 54|
 55|      // Tables have fixed height per row
 56|      if (line.startsWith('|')) {
 57|        effectiveLines += 1.5;
 58|        continue;
 59|      }
 60|
 61|      // Block content
 62|      if (line.includes('{{') || line.includes('}}')) {
 63|        effectiveLines += 1;
 64|        continue;
 65|      }
 66|
 67|      // Regular text line
 68|      effectiveLines += 1;
 69|
 70|      // Long lines wrap
 71|      if (line.length > 80) {
 72|        effectiveLines += Math.floor(line.length / 80) * 0.5;
 73|      }
 74|    }
 75|
 76|    // Detect special blocks that affect layout
 77|    const hasMonster = /\{\{monster/i.test(pageContent);
 78|    const hasWide = /\{\{.

